487|export function summarizeStageRuns(entries = [], stages = []) {
488|  const list = Array.isArray(entries) ? entries : [];
489|  const groups = new Map();
490|  const order = [];
491|  for (const entry of list) {
492|    const label = resolveTimelineStageLabel(entry?.stage, stages);
493|    if (!label) {
494|      // No stage label: never grouped, always kept as its own row.
495|      order.push({ label: null, entry });
496|      continue;
497|    }
498|    // Stage-name matching is case-insensitive everywhere else (the backend
499|    // matches names case-insensitively), so grouping is too: 'Design' and
500|    // 'design' are one stage, rendered under the first-seen spelling.
501|    const groupKey = label.toLowerCase();
502|    if (!groups.has(groupKey)) {
503|      groups.set(groupKey, { label, rows: [] });
504|      order.push({ label: groupKey, entry: null });
505|    }
506|    groups.get(groupKey).rows.push(entry);
507|  }
508|  const result = [];
509|  for (const slot of order) {
510|    if (slot.label === null) {
511|      // A copy, like every other display row: rendering must never be able
512|      // to mutate the stored timeline through this array.
513|      result.push({ ...slot.entry });
514|      continue;
515|    }
516|    const { label: displayLabel, rows: group } = groups.get(slot.label);
517|    // Representative: the chronologically latest row of the group (latest
518|    // status/reason/attribution); ties and unparseable timestamps fall back
519|    // to the first row encountered.
520|    let latest = null;
521|    let latestMs = -Infinity;
522|    for (const candidate of group) {
523|      const raw = Date.parse(candidate?.timestamp);
524|      const ms = Number.isNaN(raw) ? -Infinity : raw;
525|      // Strictly greater only: on ties (or unparseable timestamps) the first
526|      // row encountered wins — in newest-first display order that IS the
527|      // latest row.
528|      if (latest === null || ms > latestMs) {
529|        latest = candidate;
530|        latestMs = ms;
531|      }
532|    }
533|    const row = { ...latest, stage: displayLabel };
534|    // S6: infra-resume rows are re-parks, not attempts — they count into
535|    // `resumeCount`, never into `tryCount`, so the badge shows real tries
536|    // with resumes shown separately ("Tried 2 times, 4 infra resumes").
537|    const realTries = group.filter((candidate) => !isInfraResumeRow(candidate));
