44|    status === 'completed' ||
45|    status === 'done' ||
46|    status === 'failed' ||
47|    status === 'cancelled' ||
48|    status === 'waiting_human' ||
49|    status === 'paused' ||
50|    status === 'advancing' ||
51|    status === 'checkpoint' ||
52|    status === 'idle' ||
53|    status === 'running' ||
