143|    return { label: 'DONE', tone: 'done', ticking: false };
144|  }
145|  if (status === 'waiting_human' || status === 'waiting-human' || status === 'waiting') {
146|    return { label: 'WAITING', tone: 'waiting', ticking: false };
147|  }
148|  if (isTaskSettledStatus(task)) {
