232|/***
233| * MARK: formatBlockerKeys
234| * @description Formats blocker ids as short human-readable #KB-XXXX keys,
235| * capped so long blocker lists cannot break a one-line layout.
236| * @example formatBlockerKeys(['abc-1234-def']) => '#KB-ABC1'
237| * @example formatBlockerKeys(['a-1', 'b-2', 'c-3', 'd-4']) => '#KB-A1, #KB-B2, #KB-C3 +1 more'
238| * @param {Array<string>} [blockerIds=[]] - Blocker task ids.
239| * @param {Object} [options] - Formatting options.
240| * @param {number} [options.max=3] - Maximum keys shown before the +N more suffix.
241| * @returns {string} Comma-separated keys, empty string when there are no blockers.
242| ***/
243|export function formatBlockerKeys(blockerIds, { max = 3 } = {}) {
244|  if (!Array.isArray(blockerIds) || blockerIds.length === 0) return '';
245|  const limit = Number.isInteger(max) && max > 0 ? max : 3;
246|  const keys = blockerIds.map((id) => formatTaskKey(id));
247|  const shown = keys.slice(0, limit);
248|  const hidden = keys.length - shown.length;
249|  return hidden > 0 ? `${shown.join(', ')} +${hidden} more` : shown.join(', ');
