252|/***
253| * MARK: formatTaskTimestamp
254| * @description Formats real timestamp with formatted absolute time and/or relative elapsed time in stage.
255| * Never outputs hardcoded "Just now".
256| * @example formatTaskTimestamp({ enteredStageAt: '2026-08-19T09:00:00Z' }) => '9:00 AM (0m in stage)'
257| * @example formatTaskTimestamp({ timeInStage: '2m' }) => '2m in stage'
258| * @param {Object} [task] - The task object.
259| * @returns {string} Formatted timestamp string.
260| ***/
261|export function formatTaskTimestamp(task) {
262|  if (!task) return '0m in stage';
263|
264|  const tsString = task.enteredStageAt || task.updatedAt || task.createdAt || task.timestamp;
265|
266|  if (!tsString) {
267|    if (
268|      typeof task.timeInStage === 'string' &&
269|      task.timeInStage.trim() &&
270|      task.timeInStage !== 'Just now'
271|    ) {
272|      return task.timeInStage.includes('stage') ? task.timeInStage : `${task.timeInStage} in stage`;
273|    }
274|    if (typeof task.timeInStage === 'number' && task.timeInStage > 0) {
275|      return `${task.timeInStage}m in stage`;
276|    }
277|    return '0m in stage';
278|  }
279|
280|  const d = new Date(tsString);
281|  const isValidDate = !Number.isNaN(d.getTime());
282|
283|  if (!isValidDate) {
284|    if (
285|      typeof task.timeInStage === 'string' &&
286|      task.timeInStage.trim() &&
287|      task.timeInStage !== 'Just now'
288|    ) {
289|      return task.timeInStage.includes('stage') ? task.timeInStage : `${task.timeInStage} in stage`;
290|    }
291|    return '0m in stage';
292|  }
293|
294|  const timeStr = d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
295|  const now = Date.now();
296|  const elapsedMs = Math.max(0, now - d.getTime());
297|  const elapsedMinutes = Math.floor(elapsedMs / (1000 * 60));
298|  const elapsedHours = Math.floor(elapsedMinutes / 60);
299|  const elapsedDays = Math.floor(elapsedHours / 24);
300|
301|  let elapsedStr = '0m in stage';
302|  if (
303|    typeof task.timeInStage === 'string' &&
304|    task.timeInStage.trim() &&
305|    task.timeInStage !== 'Just now'
306|  ) {
307|    elapsedStr = task.timeInStage.includes('stage')
308|      ? task.timeInStage
309|      : `${task.timeInStage} in stage`;
310|    return `${timeStr} (${elapsedStr})`;
311|  }
312|
313|  if (elapsedDays > 0) {
314|    elapsedStr = `${elapsedDays}d in stage`;
315|  } else if (elapsedHours > 0) {
316|    elapsedStr = `${elapsedHours}h in stage`;
317|  } else {
318|    elapsedStr = `${elapsedMinutes}m in stage`;
319|  }
320|
321|  return `${timeStr} (${elapsedStr})`;
322|}
