335| * @param {string} [stageLabel] - Timeline stage label (legacy numeric id or name).
336| * @param {Array<Object>} [stages=[]] - The current workflow stages.
337| * @returns {string} Display label for the timeline entry.
338| ***/
339|export function resolveTimelineStageLabel(stageLabel, stages = []) {
340|  const label =
341|    stageLabel === undefined || stageLabel === null
342|      ? ''
343|      : String(stageLabel).trim();
344|  if (!label || !/^\d+$/.test(label) || !Array.isArray(stages)) return label;
345|  const match = stages.find((s) => String(s?.id) === label);
