421|  const raw = Array.isArray(rawTimeline) ? rawTimeline : [];
422|  const seen = new Set();
423|  // Stage ids are positional and can change when the workflow is edited, so
424|  // legacy numeric labels are mapped (best-effort) onto the current stage's
425|  // human-readable name for display; names pass through unchanged.
426|  const deduped = raw
427|    .map((item) => {
428|      const mapped = {
429|        ...item,
430|        stage: resolveTimelineStageLabel(item?.stage, stages),
431|      };
432|      // Fail-safe, display copies only: a non-agent stage never ran a model,
433|      // so its rows never show a badge — even for legacy stored rows that
434|      // still carry a previous agent run's fields.
435|      const record =
436|        resolveTimelineStageRecord(stages, item?.stage) ||
437|        resolveTimelineStageRecord(stages, mapped.stage);
438|      if (record && normalizeStageType(record.type) !== 'agent') {
439|        for (const key of RUN_ATTRIBUTION_KEYS) {
440|          delete mapped[key];
441|        }
442|      }
443|      return mapped;
444|    })
445|    .filter((item) => {
446|      const key = `${item.stage || ''}::${item.timestamp || ''}::${item.status || ''}::${item.duration || ''}`;
