652|  const normalized = typeof status === 'string' ? status.trim().toLowerCase() : '';
653|  return normalized === 'failed' || normalized === 'retrying' || normalized === 'resumed';
654|}
655|
656|/***
657| * MARK: pickRunAttribution
658| * @description Picks a timeline entry's run-attribution fields
659| *   (`harnessId`, `modelRef`, `aliasName`, `targetIndex`) for display,
660| *   passing only fields that exist — a row without attribution yields an
661| *   empty object, so nothing (never a placeholder) renders for it.
662| * @example pickRunAttribution({ harnessId: 'pi' }) => { harnessId: 'pi' }
663| * @example pickRunAttribution({ stage: 'CI' }) => {}
664| * @param {Object} [entry] - Timeline entry.
665| * @returns {Object} Only the attribution fields present on the entry.
666| ***/
667|function pickRunAttribution(entry) {
668|  if (!entry || typeof entry !== 'object') return {};
669|  const picked = {};
670|  for (const key of ['harnessId', 'modelRef', 'aliasName', 'targetIndex']) {
671|    if (entry[key] !== undefined) picked[key] = entry[key];
672|  }
673|  return picked;
674|}
675|
676|/***
677| * MARK: buildDisplayTimeline
678| * @description Builds the history rows the inspector shows, newest first, from
679| *   stored arrivals plus one live current-stage row. Stored arrivals record
680| *   stage = destination, so the newest arrival into the live stage would render
681| *   the same stage twice (live Active row plus stored Moved/Advanced row with
682| *   the previous stage's duration) — that row is suppressed, but only when
683| *   every stored row newer than it is a same-stage visit outcome (Failed,
684| *   Retrying, or Resumed — the live row supersedes exactly the current
685| *   visit's arrival, never a past visit's).
686| *   Failed, Completed, other-stage, and unknown-status rows are never
687| *   suppressed, so failure reasons and past visits stay visible. When the
688| *   live row supersedes the current visit's arrival row it inherits that
689| *   row's run attribution (the stage's dispatch-stamped model choice).
690| *   The stored rows are then collapsed by `summarizeStageRuns` to one row per
691| *   stage carrying a `tryCount`, so repeated failback/retry cycles render one
692| *   history line per stage ("Tried N times") instead of spamming the same
693| *   stage. Completed tasks and the full-page view pass includeLiveRow false
694| *   and see the full stored history (collapsed per stage).
695| *   A non-ticking verdict (PARKED/PAUSED/WAITING/DONE — see
696| *   `selectStagePresentation`) renders a static settled row, never a live
697| *   ACTIVE row with a growing timer.
698| * @example buildDisplayTimeline({ storedTimeline: [{ stage: 'Plan', status: 'Moved', duration: '9s', timestamp: 't2' }], stages: [{ id: '2', name: 'Plan' }], currentStageName: 'Plan', liveDurationLabel: '3s in stage', includeLiveRow: true }) => [{ stage: 'Plan', status: 'Active' }]
699| * @example buildDisplayTimeline({ storedTimeline: [], currentStageName: 'In Progress', includeLiveRow: false }) => [{ stage: 'In Progress', status: 'Active' }]
700| * @param {Object} [args] - Timeline display inputs.
701| * @param {Array<Object>} [args.storedTimeline=[]] - Stored entries, oldest first.
702| * @param {Array<Object>} [args.stages=[]] - Current workflow stages for label mapping.
703| * @param {string} [args.currentStageName] - Live stage name for the Active row.
704| * @param {string} [args.liveDurationLabel] - Live row duration text.
705| * @param {boolean} [args.includeLiveRow=false] - True for open tasks in the inspector.
706| * @param {{ label?: string, tone?: string, ticking?: boolean }} [args.presentation] - Stage presentation verdict
707| *   (see selectStagePresentation). A non-ticking verdict (PARKED/WAITING/DONE) renders a static settled
708| *   row — never a live ACTIVE row with a growing timer.
709| * @returns {Array<Object>} Display entries, most recent first. Never mutates its input.
710| ***/
711|export function buildDisplayTimeline({
712|  storedTimeline = [],
713|  stages = [],
714|  currentStageName,
715|  liveDurationLabel,
716|  includeLiveRow = false,
717|  presentation = null,
718|} = {}) {
719|  const displayStored = selectDisplayTimeline(storedTimeline, stages);
720|  const fallbackStageName =
721|    typeof currentStageName === 'string' && currentStageName.trim()
722|      ? currentStageName.trim()
723|      : 'Current Stage';
724|  if (includeLiveRow) {
725|    // Settled tasks never tick: a parked failure renders a static PARKED row
726|    // (frozen text, no growing "Nm in stage" timer) so it cannot read as live.
727|    const settledLabel =
728|      presentation && presentation.ticking === false && typeof presentation.label === 'string'
729|        ? presentation.label.trim().toUpperCase()
730|        : '';
731|    const isSettledRow =
732|      settledLabel === 'PARKED' ||
733|      settledLabel === 'PAUSED' ||
734|      settledLabel === 'WAITING' ||
735|      settledLabel === 'DONE';
736|    if (isSettledRow) {
737|      // Frozen text per verdict: the growing "Nm in stage" label would keep
738|      // moving for a task the engine will never pick up again.
739|      const settledDuration =
740|        settledLabel === 'PARKED'
741|          ? 'Parked — awaiting retry'
742|          : settledLabel === 'PAUSED'
743|            ? 'Paused'
744|            : liveDurationLabel || 'Settled';
745|      const settledName = settledLabel.charAt(0) + settledLabel.slice(1).toLowerCase();
746|      const settledRow = {
747|        stage: fallbackStageName,
748|        duration: settledDuration,
749|        timestamp: settledName,
750|        status: settledName,
751|      };
752|      return [settledRow, ...summarizeStageRuns(displayStored, stages)];
753|    }
754|    const liveRow = {
755|      stage: fallbackStageName,
756|      duration: liveDurationLabel || 'In progress',
757|      timestamp: 'Active',
758|      status: 'Active',
759|    };
760|    // The live-row suppression runs on the exact-deduped rows (one row per
761|    // stored event); the per-stage collapsing happens afterwards, on the
762|    // rows the live row did not supersede, so the current stage still renders
763|    // exactly once (live Active row) while past visits of any stage —
764|    // including the live one — collapse to one row with a try count.
765|    const arrivalIndex = displayStored.findIndex(
766|      (entry) => entry?.stage === liveRow.stage && isArrivalTimelineStatus(entry?.status),
767|    );
768|    const superseded =
769|      arrivalIndex !== -1 &&
770|      displayStored
771|        .slice(0, arrivalIndex)
772|        .every(
773|          (entry) =>
774|            entry?.stage === liveRow.stage &&
775|            isVisitOutcomeTimelineStatus(entry?.status),
776|        );
777|    if (!superseded) return [liveRow, ...summarizeStageRuns(displayStored, stages)];
778|    // The live row replaces the current visit's arrival row, so it inherits
779|    // that row's run attribution (stamped at the stage's dispatch): the
780|    // current agent run's badge stays visible while the stage is live, and a
781|    // human / CI stage's live row stays completely blank.
782|    const rest = [
783|      ...displayStored.slice(0, arrivalIndex),
784|      ...displayStored.slice(arrivalIndex + 1),
785|    ];
786|    return [
787|      { ...liveRow, ...pickRunAttribution(displayStored[arrivalIndex]) },
788|      ...summarizeStageRuns(rest, stages),
789|    ];
790|  }
791|  if (displayStored.length > 0) return summarizeStageRuns(displayStored, stages);
792|  return [
793|    {
794|      stage: fallbackStageName,
795|      duration: 'In progress',
796|      timestamp: 'Active',
797|      status: 'Active',
798|    },
799|  ];
800|}
801|
802|/***
803| * MARK: formatDiffStat
804| * @description Renders a timeline entry's per-stage lines-changed delta as
805| *   a small "+N -M" badge (added / removed lines). Returns null when the entry
806| *   carries no diff data, so legacy entries render exactly as before.
807| * @example formatDiffStat({ additions: 12, deletions: 3 }) => '+12 -3'
808| * @example formatDiffStat({ stage: 'Idea' }) => null
809| * @param {Object} [entry] - Timeline entry.
810| * @returns {string|null} Badge text, or null when there is no diff data.
811| ***/
812|export function formatDiffStat(entry) {
813|  const additions = entry?.additions;
814|  const deletions = entry?.deletions;
815|  if (!Number.isInteger(additions) || !Number.isInteger(deletions)) return null;
816|  if (additions < 0 || deletions < 0) return null;
817|  return `+${additions} -${deletions}`;
818|}

