		});
	});

	test("interrupts: collapses a hostile reason to one bounded line in marker and history", () => {
		const { executionId } = claimed(ctx);
		ledger.interruptExecution({
			claimStore: ctx.claimStore,
			taskStore: ctx.taskStore,
			projectId: "p1",
			taskId: "t1",
